import{z as o,x as s,o as e,c as d,q as i,j as n,D as a,d as B,s as t,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"公司治理的实证深化","description":"","frontmatter":{"title":"公司治理的实证深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-governance-empirical-deep.md","filePath":"econ/cf-governance-empirical-deep.md","lastUpdated":1791413859000}'),p={name:"econ/cf-governance-empirical-deep.md"};function c(D,E,C,h,m,f){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=i('<h1 id="公司治理的实证深化" tabindex="-1">公司治理的实证深化 <a class="header-anchor" href="#公司治理的实证深化" aria-label="Permalink to &quot;公司治理的实证深化&quot;">​</a></h1><div class="epigraph"><p>治理变量是公司自己选的，回归的每一行都带着选择的影子；识别治理效应之前，先问这组安排是怎么来的。</p><footer>—— 据 Gompers–Ishii–Metrick 2003 与 Bertrand–Mullainathan 2003 整理</footer></div><p><a href="/econ/cf-merger-waves">上一课</a>把接管写成外部治理：浪潮在控制权市场上替换低效管理层。可接管威胁只覆盖一部分企业——反收购条款、股权集中、双层股权都能把它挡在门外。本课写内部治理的实证：董事会、薪酬与投票权结构怎么度量、效应怎么识别。识别语言来自<a href="/econ/corporate-finance-identification">公司金融的实证识别</a>：治理与业绩的横截面回归默认有反向因果——治理差的公司，可能正是治理差被均衡选出来的结果。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>度量与识别纠缠在一起。度量侧：Gompers–Ishii–Metrick 2003 把 24 条反收购条款加总成 G 指数；Bebchuk–Cohen–Ferrell 2009 收缩为六条「侵蚀条款」。识别侧：G 指数高低组合的年化收益差可达数个百分点——但这是风险溢价、错定价，还是防御条款本身在损害价值？三种解释共用同一观测，横截面回归分不开它们。机制上，治理传导到企业价值有三条管道：纪律（接管与解聘威胁）、激励（薪酬与持股）、决策权配置（董事会与投票结构）——任何一项实证设计都必须指认自己在测哪条管道，否则读数就是三条管道的混合物。</p><p><span class="marginnote">反向因果可以翻译成「雨伞与下雨」：雨天街头雨伞多，不是雨伞招来了雨。治理与业绩同理——可能是治理带来业绩，也可能是快出事的公司才去补治理。看到相关先别急着归因，先问箭头朝哪边、能不能被外力掰动。</span></p><h3 id="准实验优先" tabindex="-1">准实验优先 <a class="header-anchor" href="#准实验优先" aria-label="Permalink to &quot;准实验优先&quot;">​</a></h3><p>横截面不行，就把变化推回外生冲击。州际反收购法通过的时间差是经典设计：Bertrand–Mullainathan 2003 发现法律通过后，CEO 少关厂、少裁员、工资上涨——「享受清闲生活」。这证明接管威胁确实在纪律经理，而不是只在改变控制权归属；纪律管道是实打实的。董事会维度：Yermack 1996 用公司固定效应找出董事会规模与托宾 \\(Q\\) 的负相关——规模与绩效在水平上互相决定，但公司内部的波动读得出边际。薪酬维度：Core–Holthausen–Larcker 1999 把薪酬-绩效敏感度低与随后的业绩差连起来，激励管道有了第一个量化锚。</p><p><span class="marginnote">直觉类比：州反收购法像突然给 CEO 撑起一把「防解雇伞」。伞一撑开，CEO 少关厂、少裁员、给自己涨工资——若接管威胁真的在纪律经理，伞下的人就该先松懈。设计的巧妙在于法律何时通过由州议会决定，公司自己选不了，箭头的方向于是被外力掰开了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>股权结构维度要升级而不是另起炉灶：<a href="/econ/family-firms-pyramids">家族企业与金字塔</a>已把投票权与现金流权的分离钉为描述工具，治理实证把它升级为识别变量——用分离度预测掏空概率与价值折价，让结构变量去解释行为而不是只贴标签。指数的用法遵循第一课的分工：指数当筛选器（标记防御文化重的公司），设计当因果（法律、规则、CEO 突逝等外生变化）。写报告时三样缺一不可：条款清单、指数构造、以及「这一设计能挡住哪类反向因果」的声明。</p>',11)),(e(),n(l,null,{default:a(()=>[t(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARRANGE%5B%22%E6%B2%BB%E7%90%86%E5%AE%89%E6%8E%92%EF%BC%9A%E8%91%A3%E4%BA%8B%E4%BC%9A%E8%96%AA%E9%85%AC%E6%8A%95%E7%A5%A8%E6%9D%83%22%5D%20--%3E%20MEAS%5B%22%E5%BA%A6%E9%87%8F%EF%BC%9A%E6%9D%A1%E6%AC%BE%E6%8C%87%E6%95%B0%E4%B8%8E%E7%BB%93%E6%9E%84%E5%8F%98%E9%87%8F%22%5D%0A%20%20MEAS%20--%3E%20CORR%5B%22%E6%A8%AA%E6%88%AA%E9%9D%A2%E7%9B%B8%E5%85%B3%22%5D%0A%20%20CORR%20--%3E%20WHY%7B%22%E5%93%AA%E7%A7%8D%E8%A7%A3%E9%87%8A%3F%22%7D%0A%20%20WHY%20--%3E%20RP%5B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20WHY%20--%3E%20MP%5B%22%E9%94%99%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20WHY%20--%3E%20ENT%5B%22%E4%BE%B5%E8%9A%80%E6%8D%9F%E5%AE%B3%E4%BB%B7%E5%80%BC%22%5D%0A%20%20QUASI%5B%22%E5%87%86%E5%AE%9E%E9%AA%8C%EF%BC%9A%E6%B3%95%E5%BE%8B%E4%B8%8E%E8%A7%84%E5%88%99%E5%86%B2%E5%87%BB%22%5D%20--%3E%20CAUS%5B%22%E6%8C%87%E8%AE%A4%E7%AE%A1%E9%81%93%E7%9A%84%E5%9B%A0%E6%9E%9C%E8%AF%81%E6%8D%AE%22%5D%0A%20%20CAUS%20--%3E%20CH%7B%22%E4%BC%A0%E5%AF%BC%E7%AE%A1%E9%81%93%22%7D%20--%3E%20DISC%5B%22%E7%BA%AA%E5%BE%8B%E6%BF%80%E5%8A%B1%E5%86%B3%E7%AD%96%E6%9D%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"为什么横截面回归不识别：治理是均衡结果——好企业「买」好治理，还是好治理造就好企业，观测上不可分；只有让治理在外生冲击下变动，两种方向才被拉开。为什么指数有效又有限：等权加总捕捉的是「防御文化」这个一阶共同因子，机械但透明，便于他人复算；代价是条款边际效应不同的信息被抹平——所以 G 指数筛得出公司，分不开条款。为什么治理证据的解读要与上一课的并购连起来：反收购条款收窄了接管威胁，等于改变外部治理的价格——治理与控制权市场不是两门学问，是同一纪律的两个价格。",-1)),(e(),n(l,null,{default:a(()=>[t(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A7%82%E6%B5%8B%EF%BC%9A%E5%A5%BD%E6%B2%BB%E7%90%86%E4%B8%8E%E5%A5%BD%E4%B8%9A%E7%BB%A9%E5%90%8C%E7%8E%B0%22%5D%20--%3E%20A%5B%22%E6%96%B9%E5%90%91%E4%B8%80%EF%BC%9A%E5%A5%BD%E4%BC%81%E4%B8%9A%E4%B9%B0%E5%BE%97%E8%B5%B7%E5%A5%BD%E6%B2%BB%E7%90%86%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E6%96%B9%E5%90%91%E4%BA%8C%EF%BC%9A%E5%A5%BD%E6%B2%BB%E7%90%86%E9%80%A0%E5%B0%B1%E5%A5%BD%E4%B8%9A%E7%BB%A9%22%5D%0A%20%20A%20--%3E%20M%5B%22%E6%A8%AA%E6%88%AA%E9%9D%A2%E5%9B%9E%E5%BD%92%E5%88%86%E4%B8%8D%E5%BC%80%E4%B8%A4%E7%A7%8D%E6%96%B9%E5%90%91%22%5D%0A%20%20B%20--%3E%20M%0A%20%20S%5B%22%E5%A4%96%E7%94%9F%E5%86%B2%E5%87%BB%EF%BC%9A%E5%B7%9E%E5%8F%8D%E6%94%B6%E8%B4%AD%E6%B3%95%E9%80%9A%E8%BF%87%22%5D%20--%3E%20C%5B%22%E6%B2%BB%E7%90%86%E5%AE%89%E6%8E%92%E8%A2%AB%E5%A4%96%E5%8A%9B%E6%94%B9%E5%8F%98%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%AF%94%E8%BE%83%E9%80%9A%E8%BF%87%E5%89%8D%E5%90%8E%E7%9A%84%E8%A1%8C%E4%B8%BA%E4%B8%8E%E4%B8%9A%E7%BB%A9%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%AE%AD%E5%A4%B4%E6%96%B9%E5%90%91%E8%A2%AB%E6%8B%89%E5%BC%80%EF%BC%8C%E5%9B%A0%E6%9E%9C%E6%89%8D%E5%8F%AF%E8%AF%BB%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">GIM 的 G 指数由 24 条条款构成，1990 年代样本里每多一条对应年化收益下降约 1% 的量级；BCF 2009 用六条侵蚀条款复现了大部分效应——等权加总虽机械，却让任何人都能从章程里重算一遍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>美国证据外推受限：投资者保护弱的市场里，主要矛盾是金字塔与隧道（<a href="/econ/family-firms-pyramids">家族企业与金字塔</a>的东亚样本），董事会细节退居其次。指数随治理实践老化，2000 年后公司普遍改良使旧条款的变异缩水。治理改革的因果证据仍然稀缺——很多「最佳实践」只是横截面相关穿了政策的外衣。本课不展开银行作为监督者的治理角色，那是后续银行课程的领域。</p><p><span class="marginnote">常见误区：把「独立董事过半、CEO 与董事长分设」当成万灵药。这些「最佳实践」多数只有横截面相关撑腰——好公司恰好这么做，不代表照抄就能变好。在没有外生冲击证据之前，抄作业的收益是个未知数，很可能是零。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>度量与识别必须分开谈：条款指数是筛选器，因果靠准实验。</li><li>Bertrand–Mullainathan 2003 证明接管威胁的纪律管道真实存在。</li><li>治理传导有三条管道——纪律、激励、决策权配置，设计必须指认测哪条。</li><li>股权结构变量要从描述升级为识别：分离度预测行为，而不是贴标签。</li><li>出处：Gompers–Ishii–Metrick 2003；Bertrand–Mullainathan 2003；Yermack 1996；Core–Holthausen–Larcker 1999；Bebchuk–Cohen–Ferrell 2009。</li></ul>',6))])}const _=o(p,[["render",c]]);export{F as __pageData,_ as default};
